  const pen = (d, w, key) =>
    `<path d="${d}" fill="none" stroke="#fff" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round" data-pen="${key}" visibility="hidden"/>`;

  const block = (d, w, m, key) =>
    `<path data-blk="${key}" d="${d}" fill="none" stroke="#000" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round" mask="url(#${m})"/>`;

